) v(kegiatan_id, nomor_st, tanggal_st, tanggal_mulai, tanggal_selesai, penugasan_id, nama_tertera, peran_tertera, tujuan, untuk)
where not exists (select 1 from sigap_surat_tugas s where s.nomor_st = v.nomor_st);

update sigap_penugasan p set surat_tugas_id = s.id
from sigap_surat_tugas s
where s.kegiatan_id = 1 and s.penugasan_id = p.id and p.surat_tugas_id is null;

-- Periode kegiatan dari ST (seragam 10 Okt - 10 Nov 2026); hanya diisi bila masih kosong.
update sigap_kegiatan set tanggal_mulai = '2026-10-10' where id = 1 and tanggal_mulai is null;
update sigap_kegiatan set tanggal_selesai = '2026-11-10' where id = 1 and tanggal_selesai is null;
